def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    bus_patches = image_patch.find("city bus")
    window_patches = image_patch.find("window")
    car_patches = image_patch.find("car")

    if not bus_patches or not window_patches or not car_patches:
        return image_patch

    bus_window_patches = [bus for bus in bus_patches for window in window_patches if bus.overlaps_with(window.left, window.lower, window.right, window.upper)]

    if not bus_window_patches:
        return image_patch

    car_depths = [(car, car.compute_depth()) for car in car_patches]
    car_depths.sort(key=lambda x: x[1])

    for bus_window in bus_window_patches:
        for car, depth in car_depths:
            if is_behind(bus_window, car):
                return bus_window

    return bus_window_patches[0]

