def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    controller_patches = image_patch.find("controller")
    wire_patches = image_patch.find("wire")

    if not controller_patches or not wire_patches:
        return image_patch

    controller_centers = [(p.left + p.right) / 2 for p in controller_patches]
    wire_centers = [(p.left + p.right) / 2 for p in wire_patches]

    for controller in controller_patches:
        closest_wire = min(wire_patches, key=lambda w: abs(controller_centers[controller_patches.index(controller)] - wire_centers[wire_patches.index(w)]))
        if closest_wire.overlaps_with(controller.left, controller.lower, controller.right, controller.upper):
            wire_patches.remove(closest_wire)

    if not wire_patches:
        return image_patch

    controller_not_chewed = [c for c in controller_patches if all(not w.overlaps_with(c.left, c.lower, c.right, c.upper) for w in wire_patches)]

    return controller_not_chewed[0] if controller_not_chewed else controller_patches[0]

