def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    red_patches = image_patch.find("red purse")
    tan_patches = image_patch.find("tan purse")
    red_and_tan_patches = red_patches + tan_patches

    if not red_and_tan_patches:
        return image_patch

    heart_patches = image_patch.find("hearts")

    if not heart_patches:
        return red_and_tan_patches[0]

    def has_hearts(patch):
        for heart in heart_patches:
            if patch.overlaps_with(heart.left, heart.lower, heart.right, heart.upper):
                return True
        return False

    red_and_tan_with_hearts = [patch for patch in red_and_tan_patches if has_hearts(patch)]

    return red_and_tan_with_hearts[0] if red_and_tan_with_hearts else red_and_tan_patches[0]

