def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    luggage_patches = image_patch.find("luggage")
    manhole_patches = image_patch.find("manhole")

    if not luggage_patches or not manhole_patches:
        return image_patch

    luggage_centers = [(p.left + p.right) / 2 for p in luggage_patches]
    manhole_centers = [(p.left + p.right) / 2 for p in manhole_patches]

    parallel_luggage = []
    for luggage in luggage_patches:
        min_distance = min(abs(luggage_center - manhole_center) for manhole_center in manhole_centers)
        if min_distance < abs(luggage.horizontal_center - manhole.horizontal_center):
            parallel_luggage.append((luggage, min_distance))

    if not parallel_luggage:
        return luggage_patches[0]

    return max(parallel_luggage, key=lambda x: x[1])[0]

